#include <stdio.h>

void countdown(int n) {
    if (n == 0) {
        printf("Blast off!\n");
        return;
    }
    printf("%d\n", n);
    countdown(n - 1);
}

int factorial(int n) {
    if (n <= 1) {
        return 1;               // base case
    }
    return n * factorial(n - 1); // recursive case
}

int main(void) {
    countdown(3);
    printf("4! = %d\n", factorial(4));
    printf("5! = %d\n", factorial(5));
    return 0;
}

